    fn new_device_auth_details(expires_in: u32) -> StandardDeviceAuthorizationResponse {
        let body = format!(
            "{{\
        \"device_code\": \"12345\", \
        \"verification_uri\": \"https://verify/here\", \
        \"user_code\": \"abcde\", \
        \"verification_uri_complete\": \"https://verify/here?abcde\", \
        \"expires_in\": {expires_in}, \
        \"interval\": 1 \
        }}"
        );

        let device_auth_url =
